// Save roster to local crystal file and build lookup tables
const fs = require('fs');
const rosterPath = '/data/crystals/context/roster.json';

const gasResponse = $input.item.json;

if (!gasResponse.success) {
  return {
    json: {
      success: false,
      error: 'GAS returned error: ' + (gasResponse.error || 'unknown'),
      message: 'Roster sync failed. Is the GAS endpoint configured?'
    }
  };
}

// Build the roster crystal
const rosterCrystal = {
  crystal_id: 'roster',
  crystal_type: 'context',
  version: 1,
  created: '2026-02-11',
  updated: new Date().toISOString().split('T')[0],
  description: 'Student roster for name lookups (LOCAL ONLY - never send to external APIs)',
  tags: ['roster', 'students', 'skey'],
  data: {
    synced: gasResponse.synced,
    student_count: gasResponse.count,
    students_without_overlord_token: gasResponse.students_without_overlord_token || 0,

    // Flat student list
    students: gasResponse.students,

    // Lookup tables for fast access
    by_skey: {},
    by_period: {}
  }
};

// Build lookup: skey → student
for (const student of gasResponse.students) {
  rosterCrystal.data.by_skey[student.skey] = {
    name: student.name,
    periods: student.periods,
    primary_period: student.primary_period
  };

  // Build lookup: period → [students]
  for (const period of student.periods) {
    const key = 'period_' + period;
    if (!rosterCrystal.data.by_period[key]) {
      rosterCrystal.data.by_period[key] = [];
    }
    rosterCrystal.data.by_period[key].push({
      skey: student.skey,
      name: student.name
    });
  }
}

// Write to file
try {
  fs.writeFileSync(rosterPath, JSON.stringify(rosterCrystal, null, 2), 'utf8');
} catch (err) {
  return {
    json: {
      success: false,
      error: 'Could not write roster crystal: ' + err.message
    }
  };
}

// Count per period
const periodCounts = {};
for (const [key, students] of Object.entries(rosterCrystal.data.by_period)) {
  periodCounts[key] = students.length;
}

return {
  json: {
    success: true,
    message: `Roster synced: ${gasResponse.count} students cached locally`,
    synced: gasResponse.synced,
    student_count: gasResponse.count,
    period_counts: periodCounts,
    students_without_overlord_token: gasResponse.students_without_overlord_token || 0
  }
};
